/**
 * Storage for `session('getOrderId')` (blueprint §5.4's session-key
 * inventory; generated by `src/lib/cartOrderId.ts`, mirroring
 * `CartController.php:283-286`).
 *
 * Same category as `src/lib/auth/flash.ts`'s cookies: a plain,
 * non-security-sensitive scalar the server itself generated (not
 * user-controlled input), so no HMAC signing is needed — unlike
 * `spaks_session`/`spaks_cart`, forging this value has no privilege or
 * cart-content implication, only cosmetic effect on the checkout page's
 * hidden `OrderId` field (`shopping-cart.blade.php`:
 * `<input type="hidden" name="OrderId" value="{{@$getOrderId}}">`).
 *
 * Lifetime matches the cart cookie (same `SESSION_LIFETIME_MINUTES`
 * coupling — source's own session key has no independent TTL either).
 */

import { cookies } from 'next/headers';
import { getCryptoConfig } from './env';

const ORDER_ID_COOKIE = 'spaks_cart_order_id';

/** Mirrors `session()->put('getOrderId', $getOrderId)`. */
export async function setCartOrderId(orderId: string): Promise<void> {
  const { sessionLifetimeMinutes } = getCryptoConfig();
  const cookieStore = await cookies();
  cookieStore.set(ORDER_ID_COOKIE, orderId, {
    httpOnly: true,
    secure: process.env.NODE_ENV === 'production',
    sameSite: 'lax',
    path: '/',
    maxAge: sessionLifetimeMinutes * 60,
  });
}

/** Mirrors `session()->get('getOrderId')` (read-only; not "read-once" —
 * source's session key persists across requests until overwritten by the
 * next add-to-cart or session expiry, unlike the flash-message cookies). */
export async function getCartOrderId(): Promise<string | null> {
  const cookieStore = await cookies();
  return cookieStore.get(ORDER_ID_COOKIE)?.value ?? null;
}
